// Live NAV page — daily NAV for the five portfolios since inception, rendered from data/live_nav.js
// (generated by Src/fund_nav.py -> Src/pc_fund_live_page.py). Nothing here is hand-typed data:
// identities, colours, fees and dealing rules are all published from the registry.

/* global Plotly */
(function () {
  const D = window.LIVE_NAV;
  const el = (id) => document.getElementById(id);
  if (!D) { el("appbar-status").textContent = "live_nav.js data missing"; return; }

  const FONT = { family: "-apple-system, Segoe UI, Roboto, sans-serif", size: 11, color: "#46535f" };
  const BASE = { font: FONT, margin: { l: 46, r: 14, t: 8, b: 30 }, paper_bgcolor: "transparent",
    plot_bgcolor: "transparent", separators: ".,",
    hoverlabel: { bgcolor: "#ffffff", bordercolor: "#dbe2ea", font: { size: 11, color: "#1b2733" }, align: "left" },
    xaxis: { gridcolor: "#eff2f6", zeroline: false, linecolor: "#e3e8ee", ticks: "", tickfont: { size: 10 } },
    yaxis: { gridcolor: "#eff2f6", zeroline: false, linecolor: "#e3e8ee", ticks: "", tickfont: { size: 10 } } };
  const CFG = { displayModeBar: false, responsive: true };

  // Plotly MUTATES the layout object it is handed — it writes `type`, `range` and `autorange` back
  // onto the axis objects. navChart was passing BASE.xaxis by reference, so once the NAV chart (date
  // x-axis) had drawn, the contribution bars inherited type:"date" and rendered their points-of-NAV
  // axis as timestamps around Dec 31 1969. Always hand Plotly freshly cloned axes. Same helper as
  // portfolios.js, for the same reason.
  const L = (extra) => {
    const e = extra || {};
    return Object.assign({}, BASE, e, {
      xaxis: Object.assign({}, BASE.xaxis, e.xaxis || {}),
      yaxis: Object.assign({}, BASE.yaxis, e.yaxis || {}),
    });
  };

  const FUNDS = D.fund_list, BENCH = D.bench_list;
  const T = D.track, F0 = D.facts[D.fund_list[0]];
  // Identity colours come from the payload, which publishes fund_registry. Never re-type them here:
  // the hand-copied map had drifted until Certain used SAA's colour and SAA used DAA's.
  const COLOR = Object.assign(
    {}, D.bench_colors || {},
    Object.fromEntries(FUNDS.map((f) => [f, (D.facts[f] || {}).color || "#3083b4"])));
  const pct = (x, d = 2) =>
    (x < 0 ? "\u2212" : "") + Math.abs(x * 100).toFixed(d) + "%";
  const pp = (x, d = 2) => (x >= 0 ? "+" : "−") + Math.abs(100 * x).toFixed(d) + "%";
  const cls = (x) => (x < 0 ? "neg" : "pos");
  const fmtD = (s) => new Date(s + "T00:00:00").toLocaleDateString("en-GB",
    { day: "numeric", month: "short", year: "numeric" });

  let fund = "SAA";   // the one selected portfolio, shared by every panel on the page

  // ---------- ribbon and page intro ----------
  // Wrapped like every other panel: these once ran bare, so a single missing payload key
  // blanked the whole page and left the footer reading "Loading…".
  function ribbon() {
    // The ribbon carries NUMBERS. An as-at date is a caption, not a headline metric — no fund page
    // makes "priced to" one of its four hero tiles, and the terms already have their own panel in
    // section 01. It also does not headline which portfolio is ahead: ranking five books on 2.4 months
    // is noise, and printing it first invites the decision the record cannot support. So the range is
    // shown as a range, low to high, with no winner named. Launch date and track-record length were
    // dropped from here too: both already sit in the terms panel below, and a date is not a metric.
    const navs = FUNDS.map((f) => D.stats[f].nav).sort((a, b) => a - b);
    const rets = FUNDS.map((f) => D.stats[f].ret).sort((a, b) => a - b);
    const dds = FUNDS.map((f) => D.stats[f].maxdd).sort((a, b) => a - b);
    el("kpi-ribbon").innerHTML = [
      { l: "NAV per unit", v: `${navs[0].toFixed(2)} – ${navs[navs.length - 1].toFixed(2)}`,
        s: `${FUNDS.length} portfolios · priced ${fmtD(D.asof)}` },
      { l: "Since launch", v: `${pp(rets[0], 1)} to ${pp(rets[rets.length - 1], 1)}`,
        s: "net of fee and dealing · not annualised" },
      { l: "From its high", v: `${pp(dds[dds.length - 1], 1)} to ${pp(dds[0], 1)}`,
        s: "deepest fall since launch" },
      { l: "Ongoing charge", v: F0.fee_bps + "bp a year", s: F0.dealing_bps + "bp per side dealt" }
    ].map((k) => `<div class="kpi${k.perf ? " kpi-perf" : ""}"><div class="kpi-label">${k.l}</div>
        <div class="kpi-value">${k.v}</div><div class="kpi-sub">${k.s}</div></div>`).join("");

    el("funds-insight").innerHTML =
      `<strong>Certain</strong> preserves purchasing power — short duration, TIPS-led, with gold and the Swiss
       franc as its store of value. <strong>Endowment</strong> is the endowment model made liquid, real assets a
       quarter of the fund. The <strong>SAA</strong> is the house policy portfolio, nine holdings and deliberately
       lean. The <strong>DAA</strong> runs that book actively, sizing its trend sleeve to the macro state — which
       reads <strong>${D.regime.toLowerCase()}</strong> today. <strong>Alpha</strong> spends an equity-level
       volatility budget of its own. None of them holds mortgage bonds.`;
    el("appbar-status").textContent = "Funds · priced to " + fmtD(D.asof);
    el("status-footer").textContent =
      "NAV from Src/fund_nav.py · books from Src/pc_fs6_build.py · priced to " + fmtD(D.asof)
      + " · not a custodial record";
  }

  // ---------- NAV cards ----------
  // The page is called Net asset value, so the net asset value is the first thing on it, as a number
  // per portfolio. The chart answers "what has it been doing"; it cannot answer "what is it".
  function spark(name) {
    const y = D.series[name], n = y.length, lo = Math.min(...y), hi = Math.max(...y);
    const rng = hi - lo || 1, W = 100, H = 30;
    const pts = y.map((v, i) => `${(i / (n - 1) * W).toFixed(2)},${(H - (v - lo) / rng * H).toFixed(2)}`);
    const base = (H - (D.nav0 - lo) / rng * H).toFixed(2);
    const up = y[n - 1] >= D.nav0;
    return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true">
      <line x1="0" x2="${W}" y1="${base}" y2="${base}" stroke="#c9ced6" stroke-width=".5"
        stroke-dasharray="2 2" vector-effect="non-scaling-stroke"/>
      <polyline points="${pts.join(" ")}" fill="none" stroke="${up ? "#1d6b43" : "#b3402f"}"
        stroke-width="1.4" vector-effect="non-scaling-stroke" stroke-linejoin="round"/></svg>`;
  }

  function navCards() {
    el("nav-cards").innerHTML = FUNDS.map((f) => {
      const st = D.stats[f], dy = D.day[f], x = D.facts[f];
      const ref = D.ref_stats[f];   // each portfolio against ITS OWN reference, not a house index
      // The since-launch NAV range — a fund page's 52-week high/low, for a fund too young to have one
      const sr = D.series[f], rng = [Math.min(...sr), Math.max(...sr)];
      const stat = (v, l, c) => `<div class="pd-stat"><b class="${c || ""}">${v}</b><span>${l}</span></div>`;
      return `<article class="pd-card nv-card" style="--pc:${COLOR[f]}">
        <div class="pd-top"><div class="pd-name">${f}</div>
          <span class="pd-kind ${x.managed === "active" ? "act" : "sta"}">${
            x.managed === "active" ? "actively run" : "policy weights"}</span></div>
        <div class="nv-head">
          <div><div class="nv-nav">${st.nav.toFixed(2)}</div>
            <div class="nv-unit">NAV per unit</div></div>
          <div class="nv-day ${cls(dy.chg)}">${dy.pts >= 0 ? "+" : "−"}${Math.abs(dy.pts).toFixed(2)}
            (${pp(dy.chg)})<div class="nv-unit" style="font-weight:500">on the day</div></div>
        </div>
        <div class="nv-spark">${spark(f)}</div>
        <div class="pd-stats">
          ${stat("$" + (10000 * st.nav / D.nav0).toFixed(0), "per $10,000", cls(st.ret))}
          ${stat(pp(st.ret), "since launch", cls(st.ret))}
          ${stat(pp(ref.excess), "vs reference", cls(ref.excess))}
          ${stat(pct(dy.dd, 1), "from its high", dy.dd < -0.0001 ? "neg" : "")}
        </div>
        <div class="pd-dials" style="margin-top:.35rem">
          <span class="pd-dial">holdings <b>${Object.keys(D.holdings[f]).length}</b></span>
          <span class="pd-dial">range <b>${rng[0].toFixed(2)}–${rng[1].toFixed(2)}</b></span>
          <span class="pd-dial">days up <b>${st.up}/${st.n}</b></span>
        </div></article>`;
    }).join("");
  }

  // ---------- NAV chart ----------
  // Three views of the same series: the level, the same thing rebased to zero so the spread is
  // readable, and the fall from each portfolio's own high — which the level chart cannot show.
  // This is a fund's NAV chart: you pick the product, you see ITS net asset value, and you pick the
  // period. That is what a product page does. The unreadable version was not the NAV — it was eight
  // series at once inside a four-point band with no period control.
  const PERIODS = [["1M", 1], ["3M", 3], ["6M", 6], ["1Y", 12], ["SI", null]];
  let period = "SI";
    let compareAll = false;   // the owner asked to be able to see all five at once — keep this
  let showRef = false;      // ...and all three references alongside them
  // Periods longer than the record are not offered — a "1Y" button on a 2.4-month fund is a lie.
  function viewChips() {
    el("nav-views").innerHTML = PERIODS.filter(([, m]) => m === null || m <= T.months)
      .map(([k]) => `<button class="chip${k === period ? " sel" : ""}" data-v="${k}">${
        k === "SI" ? "Since launch" : k}</button>`).join("")
      + `<button class="chip${showRef ? " sel" : ""}" data-v="__ref">${
        compareAll ? "Add benchmarks" : "Compare reference"}</button>`;
    el("nav-views").querySelectorAll(".chip").forEach((b) => {
      b.onclick = () => {
        if (b.dataset.v === "__ref") showRef = !showRef; else period = b.dataset.v;
        viewChips(); navChart();
      };
    });
  }

  function chips() {
    el("nav-chips").innerHTML = FUNDS.map((n) =>
      `<button class="chip${!compareAll && n === fund ? " sel" : ""}" data-n="${n}">${n}</button>`)
      .join("") + `<button class="chip${compareAll ? " sel" : ""}" data-n="__all">All five</button>`;
    el("nav-chips").querySelectorAll(".chip").forEach((b) => {
      b.onclick = () => {
        if (b.dataset.n === "__all") compareAll = true;
        else { compareAll = false; fund = b.dataset.n; }
        selectPortfolio();
      };
    });
  }
  // Chart presentation, applied to both modes.
  // Autoranging to exactly the data range over ~400px turns a 0.2% day into a 20px spike — that
  // exaggeration is what made the line read as rough. Pad the range instead. The series is NOT
  // splined: smoothing a price line invents values between real prints.
  function navAxis(vals) {
    const lo = Math.min(...vals), hi = Math.max(...vals), span = (hi - lo) || 1;
    const pad = span * 0.28;
    const step = Math.max(0.5, Math.round(((hi + pad) - (lo - pad)) / 5 * 2) / 2);
    return { range: [lo - pad, hi + pad], dtick: step };
  }
  const NAV_LAYOUT = (ax) => ({
    showlegend: false, hovermode: "x unified",
    margin: { l: 52, r: 92, t: 8, b: 30 },          // right margin holds the last-value label
    yaxis: { range: ax.range, dtick: ax.dtick, tickformat: ".2f", showgrid: true,
      gridcolor: "#eef1f5", zeroline: false, linecolor: "#e3e8ee", ticks: "",
      tickfont: { size: 10 } },
    xaxis: { type: "date", showgrid: false, linecolor: "#e3e8ee", ticks: "",
      tickfont: { size: 10 } },
    shapes: [{ type: "line", xref: "paper", x0: 0, x1: 1, y0: D.nav0, y1: D.nav0,
      line: { color: "#8a93a1", width: 1.2 } }]     // breakeven is the reference, not the faintest line
  });
  const endLabel = (x, y, color, text) => ({
    x: x, y: y, xref: "x", yref: "y", text: text, showarrow: false,
    xanchor: "left", xshift: 8, font: { size: 11, color: color, family: "inherit" },
    bgcolor: "rgba(255,255,255,0.86)", borderpad: 2
  });

  function navChart() {
    const ser = (n) => D.series[n] || (D.ref_series && D.ref_series[n]);
    // Slice to the chosen period. A NAV chart with no period control is the reason the old one was
    // unreadable: 52 points of a four-point range, squeezed against seven other series.
    const months = (PERIODS.find(([k]) => k === period) || [])[1];
    let i0 = 0;
    if (months) {
      const cut = new Date(D.dates[D.dates.length - 1] + "T00:00:00");
      cut.setMonth(cut.getMonth() - months);
      i0 = Math.max(0, D.dates.findIndex((d) => new Date(d + "T00:00:00") >= cut));
    }
    const dates = D.dates.slice(i0);
    const navOf = (n) => ser(n).slice(i0);

    const refName = D.ref_of[fund];
    // All five, optionally against all three published benchmarks. Every series is already rebased
    // to 100.00 at launch, so NAV level IS the like-for-like comparison — no second axis needed.
    if (compareAll) {
      const tr = FUNDS.map((n) => ({
        x: dates, y: navOf(n), name: n, type: "scatter", mode: "lines",
        line: { color: COLOR[n], width: 2.2 },
        hovertemplate: "%{y:.2f}<extra>" + n + "</extra>"
      })).concat(showRef ? BENCH.filter((b) => ser(b)).map((b) => ({
        x: dates, y: navOf(b), name: b, type: "scatter", mode: "lines",
        line: { color: COLOR[b] || "#b0b8c2", width: 1.3, dash: "dot" },
        hovertemplate: "%{y:.2f}<extra>" + b + "</extra>"
      })) : []);
      el("nav-chart-title").textContent = "All five portfolios — NAV per unit";
      el("nav-sub").textContent = `${period === "SI" ? "since launch" : "last " + period} · `
        + `${dates.length} trading days · every series rebased to ${D.nav0.toFixed(2)} at launch`
        + (showRef ? " · benchmarks dotted" : "");
      const allVals = tr.reduce((a, t2) => a.concat(t2.y), []);
      const lay = NAV_LAYOUT(navAxis(allVals));
      lay.showlegend = true;
      lay.legend = { orientation: "h", y: -0.18, font: { size: 10 } };
      lay.margin = { l: 52, r: 92, t: 8, b: 44 };
      lay.annotations = tr.filter((t2) => FUNDS.includes(t2.name))
        .map((t2) => endLabel(dates[dates.length - 1], t2.y[t2.y.length - 1], t2.line.color,
          t2.y[t2.y.length - 1].toFixed(2)));
      Plotly.react("nav-chart", tr, L(lay), CFG);
      const lo = FUNDS.slice().sort((a, b) => D.stats[a].nav - D.stats[b].nav);
      el("nav-read").innerHTML =
        `All five rebased to ${D.nav0.toFixed(2)} at launch, so the lines are directly comparable.
         They span ${D.stats[lo[0]].nav.toFixed(2)} to ${D.stats[lo[lo.length - 1]].nav.toFixed(2)}
         today — a ${(D.stats[lo[lo.length - 1]].nav - D.stats[lo[0]].nav).toFixed(2)} point spread in
         ${T.months.toFixed(1)} months, which is dispersion between mandates, not a ranking worth
         acting on at this length.`;
      return;
    }
    const tr = [{
      x: dates, y: navOf(fund), name: fund, type: "scatter", mode: "lines",
      line: { color: COLOR[fund], width: 1.9, shape: "linear" },
      hovertemplate: "%{y:.2f}<extra>" + fund + "</extra>"
    }];
    if (showRef && ser(refName)) {
      // The reference rebased to the fund's NAV at the start of the window, so the two are comparable
      // on one axis without a second scale.
      const r = navOf(refName), f0 = navOf(fund)[0], r0 = r[0];
      tr.push({
        x: dates, y: r.map((v) => f0 * v / r0), name: refName, type: "scatter", mode: "lines",
        line: { color: "#9aa5b1", width: 1.4, dash: "dot" },
        hovertemplate: "%{y:.2f}<extra>" + refName + " (rebased)</extra>"
      });
    }

    const lab = period === "SI" ? "since launch" : "last " + period;
    el("nav-chart-title").textContent = `${fund} — NAV per unit`;
    el("nav-sub").textContent = `${lab} · ${dates.length} trading days · priced from market closes, `
      + `net of fee and dealing`;

    const y = navOf(fund);
    const hi = Math.max(...y), lo = Math.min(...y);
    const lay = NAV_LAYOUT(navAxis(tr.reduce((a, t2) => a.concat(t2.y), [])));
    // The high, the low and today — the three points a reader looks for, labelled on the chart.
    tr.push({
      x: [dates[y.indexOf(hi)], dates[y.indexOf(lo)]], y: [hi, lo], type: "scatter", mode: "markers",
      marker: { size: 7, color: "#fff", line: { color: COLOR[fund], width: 1.6 } },
      hovertemplate: "%{y:.2f}<extra>period high / low</extra>", showlegend: false
    });
    lay.annotations = [endLabel(dates[dates.length - 1], y[y.length - 1], COLOR[fund],
      "<b>" + y[y.length - 1].toFixed(2) + "</b>")];
    Plotly.react("nav-chart", tr, L(lay), CFG);

    const a0 = navOf(fund)[0], a1 = navOf(fund)[navOf(fund).length - 1];
    const chg = a1 / a0 - 1, st = D.stats[fund], rs = D.ref_stats[fund];
    el("nav-read").innerHTML =
      `<strong>${fund}</strong> is priced at <strong>${st.nav.toFixed(2)}</strong>, from
       ${a0.toFixed(2)} at the start of this window — <strong>${pp(chg)}</strong> ${period === "SI" ? "since launch" : "over the " + period}. Its
       reference (${rs.name}) returned ${pp(rs.ret)} since launch against the fund's ${pp(st.ret)}.
       The dotted line is the ${D.nav0.toFixed(2)} launch price.`;
  }

  // ---------- tables ----------
  function perfTable() {
    // Discrete cumulative periods, the order a factsheet prints them. A period shorter than the
    // record is left blank rather than part-filled, and nothing here is annualised — see T.note.
    const ALL_COLS = [["1M", "1 month"], ["3M", "3 months"], ["6M", "6 months"],
                      ["12M", "12 months"], ["SI", "Since inception"]];
    // A column of em-dashes across every row is not information. Show a period once it has data.
    const COLS = ALL_COLS.filter(([k]) =>
      [...FUNDS, ...BENCH].some((n) => D.periods[n] && D.periods[n][k] !== null));
    el("perf-sub").textContent = `cumulative, not annualised · net of fee and dealing · `
      + `${T.trading_days} trading days priced`;
    const row = (n) => {
      const s = D.stats[n], pr = D.periods[n], isF = FUNDS.includes(n);
      const cells = COLS.map(([k]) => pr[k] === null || pr[k] === undefined
        ? `<td class="num z">—</td>`
        : `<td class="num ${cls(pr[k])}">${pp(pr[k])}</td>`).join("");
      return `<tr class="${isF ? "hl" : ""}"><td class="${isF ? "strong" : "z"}">${n}</td>
        <td class="num">${s.nav.toFixed(2)}</td>${cells}
        <td class="num">${pct(s.vol, 1)}</td><td class="num neg">${pct(s.maxdd, 1)}</td>
        <td class="num z">${s.up}/${s.n}</td></tr>`;
    };
    el("perf-table").innerHTML = `<table class="dtbl"><thead><tr><th>Fund or benchmark</th>
      <th class="num">NAV</th>${COLS.map(([k, t]) => `<th class="num" title="${t}">${k}</th>`).join("")}
      <th class="num">Vol<span class="z">†</span></th><th class="num">Worst drop</th>
      <th class="num">Days up</th></tr></thead>
      <tbody>${FUNDS.map(row).join("")}${BENCH.map(row).join("")}</tbody></table>`;
    el("perf-read").innerHTML = `${T.note} Periods longer than the record are not shown at all —
      the portfolios were launched ${T.months.toFixed(1)} months ago, so 3, 6 and 12 month columns
      would be empty. <strong>†</strong> volatility is annualised from ${T.trading_days - 1} daily observations;
      the convention is ${T.min_months_for_risk_stats} months before a risk statistic is quoted as an
      estimate, so read it as a description of this window and nothing more.`;
  }
  function monthlyTable() {
    const months = D.monthly[FUNDS[0]].map((m) => m.month);
    el("monthly-sub").textContent =
      `calendar months · first and last are partial · ${months.length} so far`;
    const head = months.map((m) => {
      const p = D.monthly[FUNDS[0]].find((x) => x.month === m);
      const d = new Date(m + "-01T00:00:00");
      return `<th class="num">${d.toLocaleDateString("en-GB", { month: "short" })}${
        p.partial ? '<span class="z">*</span>' : ""}</th>`;
    }).join("");
    const row = (n) => {
      const isF = FUNDS.includes(n);
      const cells = D.monthly[n].map((m) =>
        `<td class="num ${cls(m.ret)}">${pp(m.ret)}</td>`).join("");
      return `<tr class="${isF ? "hl" : ""}"><td class="${isF ? "strong" : "z"}">${n}</td>${cells}</tr>`;
    };
    // The references each portfolio is actually measured against, so the month-by-month comparison
    // is like-for-like rather than everything against the S&P.
    const REFS = [...new Set(FUNDS.map((f) => D.ref_of[f]))].filter((r) => !BENCH.includes(r));
    el("monthly-table").innerHTML = `<table class="dtbl"><thead><tr><th>Fund or benchmark</th>
      ${head}</tr></thead><tbody>${FUNDS.map(row).join("")}${BENCH.map(row).join("")}
      ${REFS.map(row).join("")}</tbody></table>
      <p class="read">The last rows are the blended references the portfolios are measured against,
      rebalanced daily from MSCI ACWI and the Bloomberg Aggregate. <strong>*</strong> partial month — the portfolios launched on
      ${fmtD(D.inception)} and the current month is priced to ${fmtD(D.asof)}. Monthly figures are
      cumulative within the month, net of fee and dealing.</p>`;
  }

  function relTable() {
    el("rel-sub").textContent = `cumulative excess · tracking error and beta on `
      + `${T.trading_days - 1} daily observations, indicative only`;
    let h = `<table class="dtbl"><thead><tr><th>Fund</th><th>Benchmark</th><th class="num">Excess</th>
      <th class="num">Tracking error</th><th class="num">Beta</th></tr></thead><tbody>`;
    FUNDS.forEach((f) => BENCH.forEach((b, i) => {
      const r = D.rel[f][b];
      h += `<tr class="${i === 0 ? "hl" : ""}"><td class="${i === 0 ? "strong" : ""}">${i === 0 ? f : ""}</td>
        <td class="z">${b}</td><td class="num ${cls(r.excess)}">${pp(r.excess)}</td>
        <td class="num">${pct(r.te, 1)}</td><td class="num">${r.beta.toFixed(2)}</td></tr>`;
    }));
    el("rel-table").innerHTML = h + "</tbody></table>";
  }
  function factsTable() {
    el("facts-sub").textContent =
      `base currency ${F0.currency} · ${F0.pricing.toLowerCase()} · accumulating`;
    const rows = FUNDS.map((f) => {
      const x = D.facts[f];
      return `<tr><td class="strong">${f}</td><td class="z">${x.role}</td>
        <td>${x.reference}</td><td>${x.horizon}</td>
        <td>${x.managed === "active" ? "Actively run" : "Policy weights"}</td>
        <td class="z">${x.dealing}</td></tr>`;
    }).join("");
    el("facts-table").innerHTML = `<table class="dtbl"><thead><tr><th>Portfolio</th><th>Role</th>
      <th>Reference</th><th>Horizon</th><th>Management</th><th>Dealing</th></tr></thead>
      <tbody>${rows}</tbody></table>`;
    el("facts-read").innerHTML =
      `All five carry the same terms: a <strong>${F0.fee_bps}bp</strong> annual fee accrued daily,
       <strong>${F0.dealing_bps}bp</strong> per side on anything dealt, and no single vehicle above
       <strong>${(F0.vehicle_cap * 100).toFixed(0)}%</strong> of a portfolio wherever the sleeve can be
       split across issuers. Income is reinvested — there is
       no distribution. There is deliberately <strong>no fund size, units in issue or ISIN</strong> on this
       page: these are notional portfolios priced from market closes, and a subscription record they do
       not have is not something to invent.`;
  }

  // What actually separates five multi-asset books. Not the sector split of one equity sleeve — these
  // hold equity, two bond durations, real assets, trend and cash, so the questions are how much
  // income they throw off and what they are sensitive to. Shown five-across because the difference
  // between them IS the product.
  function charsTable() {
    const C = D.chars;
    if (!C) { el("chars-sub").textContent = "characteristics not available"; return; }
    el("chars-sub").textContent =
      `income yield weighted from today's holdings · sensitivities measured, not declared`;
    const row = (label, get, fmt, hint) => `<tr><td>${label}${
      hint ? `<div class="z" style="font-size:.66rem">${hint}</div>` : ""}</td>`
      + FUNDS.map((f) => `<td class="num">${fmt(get(C[f]), C[f])}</td>`).join("") + `</tr>`;
    const n2 = (v) => v === null || v === undefined ? "—"
      : (v < 0 ? "−" : "") + Math.abs(v).toFixed(2);
    el("chars-table").innerHTML = `<table class="dtbl"><thead><tr><th>Characteristic</th>
      ${FUNDS.map((f) => `<th class="num">${f}</th>`).join("")}</tr></thead><tbody>
      ${row("Income yield", (c) => c.income_yield, (v) => pct(v, 2),
        "trailing 12m, weighted across what it holds")}
      ${row("Equity sensitivity", (c) => c.equity_beta, n2, "beta to global equity over cash")}
      ${row("Rate sensitivity", (c) => c.rate_beta, n2, "beta to rates and the curve, combined")}
      ${row("Gold", (c) => c.gold, n2, "beta to gold over cash")}
      ${row("Trend", (c) => c.trend, n2, "beta to managed futures over cash")}
      ${row("Volatility", (c) => c.vol, (v) => pct(v, 1), "annualised from the live record — short")}
      ${row("Worst drop", (c) => c.maxdd, (v) => pct(v, 1), "measured, since launch")}
      ${row("Drawdown cap", (c) => c.dd_cap, (v, c) => v === null ? "—" : pct(v, 1)
        + (c.dd_loosened ? '<span class="z">*</span>' : ""),
        "construction constraint — what the optimiser was held to")}
      ${row("Holdings", (c) => c.n_holdings, (v) => v)}
      </tbody></table>`;
    const y = FUNDS.map((f) => C[f].income_yield);
    el("chars-read").innerHTML =
      `The ladder is visible in one column: income falls from <strong>${pct(Math.max(...y), 2)}</strong>
       in ${FUNDS[y.indexOf(Math.max(...y))]} to <strong>${pct(Math.min(...y), 2)}</strong> in
       ${FUNDS[y.indexOf(Math.min(...y))]} as equity sensitivity rises from
       ${n2(C[FUNDS[0]].equity_beta)} to ${n2(C[FUNDS[FUNDS.length - 1]].equity_beta)}. That is the
       range doing what it says: the conservative books are paid to wait, the growth books are not.
       <strong>Effective duration is deliberately absent</strong> — no vehicle reports it and a figure
       invented from a maturity guess would not trace to a source, so rate sensitivity is given
       instead, measured against the rate and curve factors. The drawdown cap is a
       <strong>construction constraint</strong> — the limit the optimiser was actually held to, read
       from the build record — not a mandate limit and not a budget.${
        FUNDS.some((f) => C[f].dd_loosened)
          ? ` <strong>*</strong> ${FUNDS.filter((f) => C[f].dd_loosened).join(", ")}: the declared
             conditional-drawdown constraint (${FUNDS.filter((f) => C[f].dd_loosened)
               .map((f) => pct(C[f].cdar_declared, 0)).join(", ")}) was infeasible, so the book was
             solved under the tightest feasible pair — the cap shown is the one it was actually held
             to, not the one declared.` : ""}`;
  }

  function fundChips() {
    el("fund-chips").innerHTML = FUNDS.map((f) =>
      `<button class="chip${f === fund ? " sel" : ""}" data-f="${f}">${f}</button>`).join("");
    el("fund-chips").querySelectorAll(".chip").forEach((b) => {
      b.onclick = () => { fund = b.dataset.f; compareAll = false; selectPortfolio(); };
    });
  }
  function holdTable() {
    const h = D.holdings[fund];
    const tot = Object.values(h).reduce((a, c) => a + c, 0);
    el("hold-sub").textContent = fund + " · " + Object.keys(h).length + " holdings";
    el("hold-table").innerHTML = `<table class="dtbl"><thead><tr><th>Vehicle</th><th>Sleeve</th>
      <th class="num">Weight</th></tr></thead><tbody>` +
      Object.entries(h).sort((a, b) => b[1] - a[1]).map(([t, w]) => {
        const sl = D.ticker_sleeve[t];
        return `<tr><td class="strong">${t}</td><td class="z">${sl ? (D.labels[sl] || sl) : ""}</td>
          <td class="num">${pct(w, 1)}</td></tr>`;
      }).join("") +
      `<tr class="hl"><td class="strong">Total</td><td></td><td class="num">${pct(tot, 1)}</td></tr>
      </tbody></table>`;
    const tr = D.trades[fund] || [];
    el("trade-table").innerHTML = tr.length
      ? `<table class="dtbl"><thead><tr><th>Date</th><th class="num">Turnover</th></tr></thead><tbody>` +
        tr.map((x) => `<tr><td>${fmtD(x.date)}</td><td class="num">${x.turnover.toFixed(1)}%</td></tr>`).join("") +
        `</tbody></table>`
      : `<p class="read">Funded at inception and not dealt since — no holding has drifted a full point from target.</p>`;
    const b = D.backtest[fund];
    el("bt-table").innerHTML = `<table class="dtbl"><tbody>
      <tr><td>1997–2026 backtest</td><td class="num">${b.cagr.toFixed(2)}% a year</td></tr>
      <tr><td>Sharpe</td><td class="num">${b.sharpe.toFixed(2)}</td></tr>
      <tr><td>Worst loss</td><td class="num neg">${b.maxdd.toFixed(1)}%</td></tr></tbody></table>`;
    el("hold-read").innerHTML =
      `Weights drift with markets between rebalances, so these are today's actual weights rather than the
       targets. A sleeve above the ${(F0.vehicle_cap * 100).toFixed(0)}% vehicle cap is split across
       issuers, so no equity or bond line breaches it. The cap cannot bind a sleeve with a single
       vehicle: Certain's T-bill position is one holding and runs above it by design.
       The backtest is the long-run evidence behind ${fund} — it is a backtest, the NAV above is not.`;
  }
  // Exposure of what is HELD today, on the platform's two established taxonomies. The methodology
  // classes drive the optimiser; the platform's six drive the shared components; the crosswalk
  // between them is an owner-confirmed decision. Geography is equity-only on purpose — assigning one
  // to gold or a trend sleeve would invent a mapping that appears in no approved document.
  function exposurePanel() {
    const E = D.exposure && D.exposure[fund];
    if (!el("expo-sub")) return;
    if (!E) { el("expo-sub").textContent = "exposure not available"; return; }
    el("expo-sub").textContent = `${fund} · share of what is held today`;

    const donut = (node, obj, order, title) => {
      const keys = (order || Object.keys(obj)).filter((k) => (obj[k] || 0) > 0.005);
      Plotly.react(node, [{
        type: "pie", hole: 0.62, sort: false, direction: "clockwise",
        labels: keys, values: keys.map((k) => obj[k]),
        marker: { colors: ["#0e2233", "#3083b4", "#2f7d5e", "#d68a13", "#8a93a1", "#c0392b"],
          line: { color: "#fff", width: 1.5 } },
        textinfo: "label+percent", textposition: "outside",
        hovertemplate: "%{label}: %{value:.1f}%<extra></extra>", automargin: true
      }], L({ showlegend: false, margin: { l: 10, r: 10, t: 24, b: 10 },
        title: { text: title, font: { size: 11, color: "#46535f" }, x: 0.5, xanchor: "center" } }), CFG);
    };
    donut("expo-class", E.methodology, D.methodology_classes, "Asset class");
    if (Object.keys(E.equity_geography).length) {
      donut("expo-geo", E.equity_geography,
        ["United States", "Developed ex-US", "Emerging markets"], "Equity geography");
    } else {
      el("expo-geo").innerHTML = `<p class="read" style="padding:2rem 0">${fund} holds no equity.</p>`;
    }

    const rows = (obj, order) => (order || Object.keys(obj))
      .filter((k) => (obj[k] || 0) > 0.005)
      .map((k) => `<tr><td>${k}</td><td class="num">${obj[k].toFixed(1)}%</td></tr>`).join("");
    el("expo-table").innerHTML = `<div class="grid grid-2" style="gap:1rem">
      <div><h3 class="mini-head">Platform class</h3>
        <table class="dtbl"><thead><tr><th>Class</th><th class="num">Weight</th></tr></thead>
        <tbody>${rows(E.platform, D.platform_classes)}</tbody></table></div>
      <div><h3 class="mini-head">Sleeve</h3>
        <table class="dtbl"><thead><tr><th>Sleeve</th><th class="num">Weight</th></tr></thead>
        <tbody>${rows(E.sleeves)}</tbody></table></div></div>`;

    const us = E.equity_geography["United States"];
    el("expo-read").innerHTML =
      `${fund} holds <strong>${E.equity_weight.toFixed(1)}%</strong> in equity${
        us === undefined ? "" : `, <strong>${us.toFixed(0)}%</strong> of it in the United States`}.
       Two class views are shown because the platform keeps two on purpose: the portfolios' own
       methodology classes drive the optimiser, the platform's six drive its shared components, and
       the crosswalk between them is an owner decision — gold reads as a real asset in one and a
       commodity in the other. Geography is equity-only: gold, broad commodities and the trend sleeve
       have no defensible country of risk, so none is asserted.`;
  }

  function mandateTable() {
    const sleeves = Object.keys(D.labels).filter((s) => FUNDS.some((f) => (D.books[f][s] || 0) > 0.0005));
    let h = `<table class="dtbl"><thead><tr><th>Holding</th>` +
      FUNDS.map((f) => `<th class="num">${f}</th>`).join("") + `</tr></thead><tbody>`;
    D.classes.forEach((c) => {
      const mem = sleeves.filter((s) => D.class_of[s] === c);
      if (!mem.length) return;
      h += `<tr class="hl"><td class="strong">${c}</td>` + FUNDS.map((f) => {
        const t = mem.reduce((a, s) => a + (D.books[f][s] || 0), 0);
        return `<td class="num">${t > 0.0005 ? pct(t, 1) : "–"}</td>`;
      }).join("") + `</tr>`;
      mem.forEach((s) => {
        h += `<tr><td class="z" style="padding-left:1.2rem">${D.labels[s]}</td>` + FUNDS.map((f) => {
          const w = D.books[f][s] || 0;
          return `<td class="num">${w > 0.0005 ? pct(w, 1) : "<span class=\"z\">–</span>"}</td>`;
        }).join("") + `</tr>`;
      });
    });
    h += `<tr class="hl"><td class="strong">Horizon</td>` +
      FUNDS.map((f) => `<td class="num z">${D.funds[f].horizon}</td>`).join("") + `</tr>`;
    el("mandate-table").innerHTML = h + "</tbody></table>";
  }

  // ---------- what moved the NAV ----------
  // fund_nav.py scales each day's contribution by the NAV level it was earned on and refuses to write
  // a bridge that does not reconcile, so these pieces sum to the NAV exactly. The page states the sum
  // rather than asking the reader to trust it.
  function bridgeChips() {
    el("bridge-chips").innerHTML = FUNDS.map((f) =>
      `<button class="chip${f === fund ? " sel" : ""}" data-f="${f}">${f}</button>`).join("");
    el("bridge-chips").querySelectorAll(".chip").forEach((b) => {
      b.onclick = () => { fund = b.dataset.f; compareAll = false; selectPortfolio(); };
    });
  }
  // ---------- what the book was EXPOSED to ----------
  // The holdings bridge says which line moved the NAV. This says what the book was positioned in and
  // what that position paid. Exposures are not estimated from the fund's own 51 days — that would be
  // noise — they are the real daily weights times each vehicle's betas, fitted on years of history.
  // Whatever the factors do not explain is shown as a residual rather than spread over them.
  function facPanel() {
    const FA = D.factor;
    if (!FA) { el("fac-sub").textContent = "factor attribution not available"; return; }
    const A = FA.funds[fund], w = FA.window;
    el("fac-sub").textContent = `${fund} · ${FA.factor_defs.length} factors · `
      + `betas fitted on ${w.beta_obs} days from ${w.beta_start} · points of NAV`;

    const rows = A.factors.map((f) => [f.name, f.contrib, f])
      .concat([["Cash", A.cash, null], ["Costs", A.costs, null], ["Unexplained", A.residual, null]])
      .sort((a, b) => b[1] - a[1]);

    Plotly.react("fac-chart", [{
      type: "bar", orientation: "h",
      y: rows.map((r) => r[0]).reverse(), x: rows.map((r) => r[1]).reverse(),
      marker: { color: rows.map((r) => r[2] === null ? (r[1] >= 0 ? "#6f8ea6" : "#c08a80")
        : (r[1] >= 0 ? "#2f7d5e" : "#b3402f")).reverse() },
      hovertemplate: "%{y}: %{x:+.3f} pts<extra></extra>"
    }], L({
      showlegend: false, bargap: 0.28, margin: { l: 96, r: 18, t: 6, b: 28 },
      xaxis: { type: "linear", title: { text: "points of NAV", font: { size: 10 } },
        zeroline: true, zerolinecolor: "#b8c0ca" },
      yaxis: { type: "category", automargin: true }
    }), CFG);

    const num = (v, d = 3) => `${v >= 0 ? "+" : "−"}${Math.abs(v).toFixed(d)}`;
    const fr = A.factors.map((f) => `<tr><td>${f.name}<div class="z" style="font-size:.66rem">${
      f.blurb}</div></td><td class="num">${f.exposure >= 0 ? "" : "−"}${
      Math.abs(f.exposure).toFixed(2)}</td><td class="num ${cls(f.fret)}">${pp(f.fret, 1)}</td>
      <td class="num ${cls(f.contrib)}">${num(f.contrib)}</td></tr>`).join("");
    el("fac-table").innerHTML = `<table class="dtbl"><thead><tr><th>Factor</th>
      <th class="num">Exposure</th><th class="num">Factor</th><th class="num">Points</th></tr></thead>
      <tbody>${fr}
      <tr><td>Cash<div class="z" style="font-size:.66rem">earned on the whole book</div></td>
        <td class="num z">1.00</td><td class="num z">—</td>
        <td class="num ${cls(A.cash)}">${num(A.cash)}</td></tr>
      <tr><td>Costs<div class="z" style="font-size:.66rem">fee and dealing</div></td>
        <td class="num z">—</td><td class="num z">—</td>
        <td class="num ${cls(A.costs)}">${num(A.costs)}</td></tr>
      <tr><td>Unexplained<div class="z" style="font-size:.66rem">what the factors do not account for</div></td>
        <td class="num z">—</td><td class="num z">—</td>
        <td class="num ${cls(A.residual)}">${num(A.residual)}</td></tr>
      <tr class="hl"><td><strong>Net asset value</strong></td><td class="num z">—</td>
        <td class="num z">—</td><td class="num ${cls(A.total)}">${num(A.total)}</td></tr>
      </tbody></table>`;

    const byAbs = A.factors.slice().sort((a, b) => Math.abs(b.contrib) - Math.abs(a.contrib));
    const sz = A.factors.find((f) => f.name === "Size"), va = A.factors.find((f) => f.name === "Value");
    el("fac-read").innerHTML =
      `<strong>${byAbs[0].name}</strong> is the exposure that mattered most for ${fund}
       (${num(byAbs[0].contrib, 2)} points, from an exposure of ${byAbs[0].exposure.toFixed(2)} to a
       factor that returned ${pp(byAbs[0].fret, 1)}), then <strong>${byAbs[1].name}</strong> at
       ${num(byAbs[1].contrib, 2)}. On the size and style dimensions the methodology formalises as the
       3x3 style box, this
       book takes essentially no bet: <strong>size ${sz.exposure.toFixed(2)}</strong> and
       <strong>value ${va.exposure.toFixed(2)}</strong>. Small beat big by ${pp(sz.fret, 1)} and value
       by ${pp(va.fret, 1)} over the window, so not taking those bets was worth
       ${num(sz.contrib + va.contrib, 2)} points — a non-decision with a visible price, which is the
       argument for deciding it deliberately rather than by default.
       <strong>${num(A.residual, 2)}</strong> is unexplained: vehicle behaviour the thirteen factors
       do not span, shown rather than folded into them.`;
  }

  function bridgePanel() {
    const B = D.bridge[fund];
    const lab = (k) => (D.labels && D.labels[k]) ? D.labels[k] : k;
    const items = Object.entries(B.sleeves).map(([k, v]) => [lab(k), v])
      .concat([["Dealing", B.dealing], ["Fee", B.fee]])
      .sort((a, b) => b[1] - a[1]);
    el("bridge-sub").textContent =
      `${fund} · in points of NAV · sums to ${pp(B.total / 100)} since ${fmtD(D.inception)}`;

    Plotly.react("bridge-chart", [{
      type: "bar", orientation: "h",
      y: items.map((i) => i[0]).reverse(), x: items.map((i) => i[1]).reverse(),
      marker: { color: items.map((i) => i[1] >= 0 ? "#2f7d5e" : "#b3402f").reverse() },
      hovertemplate: "%{y}: %{x:+.3f} pts<extra></extra>"
    }], L({
      showlegend: false, bargap: 0.3,
      margin: { l: 132, r: 18, t: 6, b: 28 },
      xaxis: { type: "linear", title: { text: "points of NAV", font: { size: 10 } },
        zeroline: true, zerolinecolor: "#b8c0ca" },
      yaxis: { type: "category", automargin: true }
    }), CFG);

    const r = (n, v, c) => `<tr class="${c || ""}"><td>${n}</td>
      <td class="num ${cls(v)}">${v >= 0 ? "+" : "−"}${Math.abs(v).toFixed(3)}</td></tr>`;
    const veh = Object.entries(B.vehicles).sort((a, b) => b[1] - a[1]);
    el("bridge-table").innerHTML = `<h3 class="mini-head">By vehicle</h3>
      <table class="dtbl"><thead><tr><th>Vehicle</th><th class="num">Points</th></tr></thead><tbody>
      ${veh.map(([k, v]) => r(k + ' <span class="z">' + lab(D.ticker_sleeve[k] || "") + "</span>", v)).join("")}
      ${r("Dealing", B.dealing)}${r("Fee", B.fee)}
      ${r("<strong>Net asset value</strong>", B.total, "hl")}</tbody></table>`;

    const top = items.filter((i) => i[1] > 0)[0], worst = items[items.length - 1];
    el("bridge-read").innerHTML =
      `${fund} is ${pp(B.total / 100)} since launch. <strong>${top[0]}</strong> is the largest
       positive contributor at ${top[1] >= 0 ? "+" : "−"}${Math.abs(top[1]).toFixed(2)} points and
       <strong>${worst[0]}</strong> the largest drag at ${worst[1] >= 0 ? "+" : "−"}${
        Math.abs(worst[1]).toFixed(2)}. Costs took ${Math.abs(B.dealing + B.fee).toFixed(3)} points —
       ${Math.abs(B.fee).toFixed(3)} of it the management fee. Contributions are measured on the NAV
       level each day's return was earned on, so the column adds to the NAV exactly.`;
  }

  function disclosure() {
    const items = [
      ["Past performance", `Past performance is not a guide to future performance. The record is
        ${T.months.toFixed(1)} months long — below the ${T.min_months_to_annualise} months at which a return
        is annualised and well below the ${T.min_months_for_risk_stats} at which risk statistics are
        normally quoted. <strong>No return on this page is annualised.</strong> Volatility and tracking
        error are annualised from daily observations, and the long-run backtest figures are stated per
        year — each is labelled where it appears.`],
      ["Two different things called performance", `The series on this page is the <strong>live</strong>
        NAV from ${fmtD(D.inception)}. The 1997–2026 figures elsewhere on the platform are a
        <strong>backtest of today's weights</strong> — a different basis, and they are not linked to or
        continued by this record.`],
      ["How the NAV is struck", `Daily, from dividend-adjusted closing prices of the vehicles actually
        held, in ${F0.currency}. A ${F0.fee_bps}bp annual fee accrues daily and ${F0.dealing_bps}bp per
        side is charged on anything dealt. The whole series is recomputed from inception on every run,
        so a corrected price corrects the history rather than leaving a step in it.`],
      ["What this is not", `Not a custodial or audited record, not a price you could have dealt at, and
        not a fund you can buy. There is no fund size, no units in issue and no ISIN because there are
        no subscriptions — these are notional portfolios priced against the market.`],
      ["Data", `Vehicle prices from a public market-data feed (exploratory tier); the cash sleeve uses a
        FRED T-bill proxy; regime state from the Macro-Regime-Score platform. Priced to
        ${fmtD(D.asof)}.`]
    ];
    el("disclosure").innerHTML = items.map(([h, b]) =>
      `<div class="vi"><div class="vi-l">${h}</div><div class="vi-v">${b}</div></div>`).join("");
  }

  // Each panel runs independently. These were one statement: when sbxPanel threw — its markup had
  // moved to another page — every panel after it silently did not render, and the page still
  // reported clean because the status footer had already been written. A failure now names itself
  // and the rest of the page still renders.
  const PANELS = [["ribbon", ribbon], ["NAV cards", navCards], ["periods", viewChips], ["portfolio chips", chips],
    ["terms", factsTable], ["characteristics", charsTable], ["NAV chart", navChart],
    ["discrete returns", perfTable], ["monthly", monthlyTable], ["benchmarks", relTable],
    ["attribution chips", bridgeChips], ["exposure attribution", facPanel],
    ["holdings bridge", bridgePanel], ["holdings chips", fundChips], ["holdings", holdTable],
    ["exposure", exposurePanel], ["mandates", mandateTable], ["disclosure", disclosure]];
  // Every panel that depends on which portfolio is selected, re-run together.
  function selectPortfolio() {
    [chips, viewChips, navChart, bridgeChips, facPanel, bridgePanel, fundChips, holdTable,
     exposurePanel].forEach((fn) => {
      try { fn(); } catch (e) { console.error("[live] re-render:", e); }
    });
  }

  const broke = [];
  PANELS.forEach(([name, fn]) => {
    try { fn(); } catch (e) { broke.push(name); console.error("[live] " + name + ":", e); }
  });
  if (broke.length && el("status-footer")) {
    el("status-footer").textContent =
      `Error: ${broke.length} panel(s) failed to render — ${broke.join(", ")}.`;
  }
})();
